                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        # reference Conv3d to obtain initialized weights
        ref = nn.Conv3d(in_channels,
                        out_channels,
                        kernel_size=(kernel_size, kernel_size, kernel_size),
                        stride=stride,
                        padding=padding,
                        dilation=dilation,
                        groups=groups,
                        bias=bias)
        self.weight = nn.Parameter(ref.weight.detach().clone().half().contiguous())
