                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        # reference Conv3d to obtain initialized weights
        ref = nn.Conv3d(in_channels,
                        out_channels,
                        kernel_size=(kernel_size, kernel_size, kernel_size),
                        stride=stride,
                        padding=padding,
                        dilation=dilation,
                        groups=groups,
                        bias=bias)
        self.weight = nn.Parameter(ref.weight.detach().clone().half().contiguous())
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.kernel_size = kernel_size

        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def _out_shape(self, D_in, H_in, W_in):
        K = self.kernel_size
        S = self.stride
        P = self.padding
        D = self.dilation
        D_out = (D_in + 2 * P - D * (K - 1) - 1) // S + 1
        H_out = (H_in + 2 * P - D * (K - 1) - 1) // S + 1
        W_out = (W_in + 2 * P - D * (K - 1) - 1) // S + 1
        return D_out, H_out, W_out

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, Cin, D_in, H_in, W_in = x.shape
        Cout = self.weight.shape[0]

        D_out, H_out, W_out = self._out_shape(D_in, H_in, W_in)

        out = torch.empty((N, Cout, D_out, H_out, W_out),
                         dtype=torch.half,
                         device=x.device)

        total = N * Cout * D_out * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            N,
            Cin,
            Cout,
            D_in,
            H_in,
            W_in,
            D_out,
            H_out,
            W_out,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        ]

        ptx_launch(self.module,
                   "conv3d_fp16",
                   grid,
                   (block, 1, 1),
                   args)

        return out
